import { persistOptions, withLenses } from '@dhmk/zustand-lens';
import { create } from 'zustand';
import { devtools, persist } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';
import { createSuperAppSlice, SuperAppState } from '~/entities/super-app/model/store';
import { AppConfigState, createAppConfigSlice } from '~/entities/app-config/model/store';
import { AuthState, createAuthSlice } from '~/entities/auth/model/store';
import { ExchangeState, createExchangeSlice } from '~/entities/exchange/model/store';
import { createPinSlice } from '~/entities/pin/model/store';
import { PinState } from '~/entities/pin/model/types';
import { createQRScannerSlide, QRScannerState } from '~/entities/qr-scan/model/store';
import { StorageKeys } from '~/shared/config/local-storage';

export type RootStore = {
  authSlice: AuthState;
  superAppSlice: SuperAppState;
  appConfigSlice: AppConfigState;
  qrScannerSlice: QRScannerState;
  exchangeSlice: ExchangeState;
  pinSlice: PinState;
};

export const useStore = create<RootStore>()(
  devtools(
    persist(
      immer(
        withLenses(() => ({
          ...persistOptions({
            save(state) {
              // state에서 필요한 데이터만 저장하는 로직
            },
            load(persistedState) {
              const state = persistedState as RootStore;
              // 복원할 때 사용할 데이터를 정의
              return state;
            },
          }),
          authSlice: createAuthSlice,
          superAppSlice: createSuperAppSlice,
          appConfigSlice: createAppConfigSlice,
          qrScannerSlice: createQRScannerSlide, // feature 로  독립적으로 관리해도 될지 검토 필요
          exchangeSlice: createExchangeSlice,
          pinSlice: createPinSlice,
        })),
      ),
      {
        name: StorageKeys.RootStore,
        version: 3,
        ...persistOptions,
      },
    ),
  ),
);

type StoreWithPersist = typeof useStore;

export const withStorageDOMEvents = (store: StoreWithPersist) => {
  const storageEventCallback = (e: StorageEvent) => {
    if (e.key === store.persist.getOptions().name && e.newValue) {
      store.persist.rehydrate();
    }
  };

  window.addEventListener('storage', storageEventCallback);
  return () => {
    window.removeEventListener('storage', storageEventCallback);
  };
};

withStorageDOMEvents(useStore);

// 개발 환경에서 Cypress가 zustand 상태를 접근할 수 있도록 전역에 노출
if (window.Cypress) {
  window.store = useStore;
}
