import { lens } from '@dhmk/zustand-lens';
import { AllQRCode } from '~/entities/qr-code/model/types';
import { determineQRScanType } from '~/entities/qr-scan/model/determineQRScanType';
import { QRScanOptions, ScannerType } from '~/entities/qr-scan/model/types';
import { MPMQrScanType } from '~/shared/api/dtos/enums';

export type QRScannerState = {
  options: QRScanOptions;
  QRCode: AllQRCode;
  resetQRCode: () => void;
  resetQRCodeState: () => void;
  resetOptions: () => void;

  setQRCode(QRCode: AllQRCode): void;

  setOptions(options: QRScanOptions): void;

  hasTxCode(QRCode?: AllQRCode): boolean;

  hasWalletAddr(QRCode?: AllQRCode): boolean;

  hasAliasNm(QRCode?: AllQRCode): boolean;

  hasPayAmount(QRCode?: AllQRCode): boolean;

  isValid(): boolean;
};

const initialState = {
  isVisibleQRScan: false,
  options: {
    scannerType: ScannerType.PaymentQRScan,
    to: '',
    from: '',
  } as QRScanOptions,
  QRCode: {
    tag: '',
    length: '',
    value: '',
    name: '',
  } as AllQRCode,
};

export const createQRScannerSlide = lens<QRScannerState>((set, get) => ({
  ...initialState,
  setQRCode: (QRCode) => {
    const hasTxCode = get().hasTxCode(QRCode);
    const hasPayAmount = get().hasPayAmount(QRCode);
    const hasWalletAddr = get().hasWalletAddr(QRCode);
    const hasAliasNm = get().hasAliasNm(QRCode);
    const { from } = get().options;
    const options = { ...get().options };

    options.qrScanType = determineQRScanType({ hasTxCode, hasPayAmount, hasWalletAddr, hasAliasNm, from });
    set({ QRCode, options });
  },
  setOptions: (options) => {
    set({ options });
  },
  resetOptions: () => {
    set({ options: initialState.options });
  },
  resetQRCode: () => {
    set({ QRCode: initialState.QRCode });
  },
  resetQRCodeState: () => {
    set(initialState);
  },
  hasTxCode: (QRCode) => {
    const txCode = QRCode ? QRCode.txCode : get().QRCode?.txCode;
    let hasTxCodeVal = !!txCode && txCode.length > 0;
    if (QRCode?.mpmType === MPMQrScanType.고정형) {
      const aliasNm = QRCode ? QRCode.aliasNm : get().QRCode?.aliasNm;
      hasTxCodeVal = !!aliasNm && aliasNm.length > 0;
    }
    return hasTxCodeVal;
  },
  hasPayAmount: (QRCode) => {
    const payAmount = QRCode ? QRCode.amount : get().QRCode?.amount;
    return !!payAmount && Number(payAmount) > 0;
  },
  hasWalletAddr: (QRCode) => {
    const walletAddr = QRCode ? QRCode.walletAddr : get().QRCode?.walletAddr;
    return !!walletAddr && walletAddr.length > 0;
  },
  hasAliasNm: (QRCode) => {
    const aliasNm = QRCode ? QRCode.aliasNm : get().QRCode?.aliasNm;
    return !!aliasNm && aliasNm.length > 0;
  },
  isValid: () => {
    return get().hasTxCode() || get().hasWalletAddr() || get().hasAliasNm();
  },
}));
