import { QRScanType } from '~/entities/qr-scan/model/types';
import { PATHS } from '~/shared/routes/paths';

type Props = {
  hasTxCode: boolean;
  hasPayAmount: boolean;
  hasWalletAddr: boolean;
  hasAliasNm: boolean;
  from: string;
};

export const determineQRScanType = ({ hasTxCode, hasPayAmount, hasWalletAddr, hasAliasNm, from }: Props) => {
  if (hasTxCode || hasAliasNm) {
    return hasPayAmount ? QRScanType.QR_결제하기_결제금액포함 : QRScanType.QR_결제하기_결제금액없음;
  }

  if (hasWalletAddr) {
    return from.includes(`${PATHS.exchange.root}`)
      ? QRScanType.QR_지갑주소입력_수신자선택
      : QRScanType.QR_지갑주소입력_수신자입력;
  }

  return QRScanType.QR_결제하기_결제금액포함;
};
