import * as Sentry from '@sentry/react';
import { useQuery } from '@tanstack/react-query';
import axios from 'axios';
import { produce } from 'immer';
import { partialUserDataSchema, validatePartialUserData } from '~/entities/pin/api/dtos/schemas';
import { UserResponse } from '~/entities/pin/api/dtos/types';
import { transformUserWithTokenList } from '~/entities/user/lib/transform-user-with-token-list';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { WalletUseYN } from '~/shared/api/dtos/enums';
import { queries } from '~/shared/api/query-keys';
import { appConfig } from '~/shared/config';
import { getGlobalQueryClient } from '~/shared/config/query';
import { resultify } from '~/shared/lib/utils/resultify';
import { defaultData } from './dtos/default-value';

const userDetailQueryKey = queries.cstr.cstmr({ cstmrNo: 'detail' }).queryKey;

export const getCstmr = () => async () => {
  try {
    return await resultify(axios.get<UserResponse>(`${API_URLS.cstmr('detail')}`));
  } catch (error) {
    const cachedUserRes = getGlobalQueryClient().getQueryData<UserResponse>(userDetailQueryKey);

    if (cachedUserRes?.tbCstmrMastr?.priAliasNm === null) {
      return cachedUserRes;
    }

    throw error;
  }
};

export const useGetUserInfoQuery = (options?: QueryOptions<UserResponse, CBDCAxiosError, UserResponse>) => {
  return useQuery<UserResponse, CBDCAxiosError, UserResponse>({
    queryKey: userDetailQueryKey,
    queryFn: getCstmr(),
    // refetchOnMount: false,
    // refetchOnWindowFocus: false,
    // refetchOnReconnect: false,
    throwOnError: true,
    notifyOnChangeProps: ['data'],
    networkMode: 'offlineFirst',
    staleTime: 1000 * 60,
    gcTime: Infinity,
    retry: false,
    initialData: defaultData,
    select: (data) => {
      const userInfo = transformUserWithTokenList(data.tbCstmrMastr);
      const scope = Sentry.getGlobalScope();
      scope.setUser({
        id: userInfo.cstmrNo ?? '',
        username: userInfo.koreanNm ?? '',
      });
      scope.setExtra('userInfo', userInfo);
      scope.setExtra('appConfig', appConfig);
      scope.setExtra('appConfig', appConfig);
      const isWalletBlocked = userInfo.useYn === WalletUseYN.블랙리스트;
      const hasWallet = !!userInfo.walletId;

      const newUserResponse: UserResponse = {
        tbCstmrMastr: {
          ...data.tbCstmrMastr,
          ...userInfo,
          isWalletBlocked,
          hasWallet,
        },
        transkeyModel: data?.transkeyModel ?? null,
        editable: !!data?.editable,
      };
      return newUserResponse;
    },
    ...options,
  });
};

export const setUserRes = (updater: (prev: UserResponse) => Partial<UserResponse>) => {
  const queryClient = getGlobalQueryClient();

  queryClient.setQueryData(userDetailQueryKey, (old: UserResponse) => {
    const newData = updater(old);

    try {
      // Zod 스키마를 사용한 런타임 타입 검증
      // 정의되지 않은 속성을 포함하면 오류가 발생합니다
      const validatedData = validatePartialUserData(newData);

      // console.log('newData', newData);
      // console.log('validatedData', validatedData);
      // console.log('old', old);

      return produce(old, (draft) => {
        Object.assign(draft, validatedData);
      });
    } catch (error) {
      console.error('타입 검증 오류:', error);

      // 타입 오류가 있어도 기존 필드에 대한 업데이트는 진행
      // 하지만 타입에 없는 속성은 제외됩니다
      const safeUpdate = partialUserDataSchema.safeParse(newData);
      if (safeUpdate.success) {
        return produce(old, (draft) => {
          Object.assign(draft, safeUpdate.data);
        });
      }

      return old;
    }
  });
};

export const getUserRes = (): UserResponse => {
  const queryClient = getGlobalQueryClient();
  return queryClient.getQueryData<UserResponse>(userDetailQueryKey) ?? defaultData;
};

export const resetUserInfo = () => {
  setUserRes((_prev) => ({
    ...defaultData,
  }));
};
