import { lens } from '@dhmk/zustand-lens';
import { SetStateAction } from 'react';
import { PathType } from '~/shared/routes/paths';

// 리디렉션 처리 진행 중 여부를 추적 (렌더링 사이클과 무관)
let isProcessingRedirect = false;

export type AppConfigState = {
  isHideBalance: boolean;
  isLargeFontSizeEnabled: boolean;
  appVersion: string;
  redirectPath?: PathType;
  hasPushTokenSent: boolean;
  notiBarMessage?: string;
  snackBarMessage?: string;
  setIsHideBalance: (update: SetStateAction<boolean>) => void;
  setAppVersion: (appVersion: string) => void;
  setIsLargeFontSizeEnabled: (update: SetStateAction<boolean>) => void;
  resetIsLargeFontSize: () => void;
  setRedirectPath: (redirectPath: PathType) => void;
  resetRedirectPath: () => void;
  safeResetRedirectPath: () => void; // 안전한 리셋 (중복 호출 방지)
  getFormattedRedirectPath: () => string | null; // 경로를 문자열로 변환
  setHasPushTokenSent: (hasPushTokenSent: boolean) => void;
  resetHasPushTokenSent: () => void;
  setNotiBarMessage: (notiBarMessage: string) => void;
  setSnackBarMessage: (snackBarMessage: string) => void;
};

export type UtilEvents = Pick<AppConfigState, 'redirectPath' | 'notiBarMessage' | 'snackBarMessage'>;

export const DEFAULT_APP_VERSION = '1.0';

const initialState = {
  isLargeFontSizeEnabled: false,
  appVersion: DEFAULT_APP_VERSION,
  redirectPath: '',
  hasPushTokenSent: false,
} as AppConfigState;

export const createAppConfigSlice = lens<AppConfigState>((set, get) => ({
  ...initialState,
  setIsHideBalance: (update) => {
    set((state: AppConfigState) => {
      const newIsHideBalance = typeof update === 'function' ? update(state.isHideBalance) : update;
      return {
        ...state,
        isHideBalance: newIsHideBalance,
      };
    });
  },
  setAppVersion: (appVersion: string) => {
    set((state: AppConfigState) => {
      return {
        ...state,
        appVersion,
      };
    });
  },
  setIsLargeFontSizeEnabled: (update) => {
    set((state: AppConfigState) => {
      const newIsLargeFontSizeEnabled = typeof update === 'function' ? update(state.isLargeFontSizeEnabled) : update;
      return {
        ...state,
        isLargeFontSizeEnabled: newIsLargeFontSizeEnabled,
      };
    });
  },
  resetIsLargeFontSize: () => {
    set((state: AppConfigState) => {
      return {
        ...state,
        isLargeFontSizeEnabled: initialState.isLargeFontSizeEnabled,
      };
    });
  },
  setRedirectPath: (redirectPath) => {
    set((state: AppConfigState) => {
      return {
        ...state,
        redirectPath,
      };
    });
  },
  resetRedirectPath: () => {
    set((state: AppConfigState) => {
      return {
        ...state,
        redirectPath: initialState.redirectPath,
      };
    });
  },
  // 안전한 리셋 - 중복 호출 방지 로직 포함
  safeResetRedirectPath: () => {
    const state = get();

    // 리셋할 경로가 없거나 이미 처리 중이면 무시
    if (!state.redirectPath || isProcessingRedirect) {
      return;
    }

    try {
      isProcessingRedirect = true;

      // 다음 틱으로 지연하여 렌더링 사이클과 분리
      setTimeout(() => {
        set((currentState: AppConfigState) => ({
          ...currentState,
          redirectPath: initialState.redirectPath,
        }));
      }, 0);
    } finally {
      // 다음 이벤트 루프에서 플래그 해제
      setTimeout(() => {
        isProcessingRedirect = false;
      }, 0);
    }
  },
  // 리디렉션 경로를 문자열로 변환하여 반환
  getFormattedRedirectPath: () => {
    const { redirectPath } = get();
    if (!redirectPath) return null;

    return typeof redirectPath === 'object' ? `${redirectPath}` : redirectPath;
  },
  setHasPushTokenSent: (hasPushTokenSent) => {
    set((state: AppConfigState) => {
      return {
        ...state,
        hasPushTokenSent,
      };
    });
  },
  resetHasPushTokenSent: () => {
    set((state: AppConfigState) => {
      return {
        ...state,
        hasPushTokenSent: initialState.hasPushTokenSent,
      };
    });
  },
  setNotiBarMessage: (notiBarMessage) => {
    set((state: AppConfigState) => {
      return {
        ...state,
        notiBarMessage,
      };
    });
  },
  setSnackBarMessage: (snackBarMessage) => {
    set((state: AppConfigState) => {
      return {
        ...state,
        snackBarMessage,
      };
    });
  },
}));
