import { AxiosError } from 'axios';
import { ZodError } from 'zod';
import i18n from '~/shared/i18n/i18n';
import { checkIsKickOutError, checkNoPermission, KickOutError } from '..';

export type ErrorMessage = {
  title?: string;
  message: string;
};

export const parseError = (error: any): ErrorMessage => {
  let message: string | undefined;

  if (checkIsKickOutError(error)) {
    throw new KickOutError(error);
  }

  if (checkNoPermission(error)) {
    throw new KickOutError(error.response?.data?.message);
  }
  // 1. error.response.data.message 확인
  if (error instanceof AxiosError) {
    message = error.response?.data?.message;
  }
  // 2. ZodError 확인
  else if (error instanceof ZodError) {
    message = error.errors[0]?.message;
  }
  // 3. error.message 확인
  else if (error instanceof Error) {
    message = error.message;
  }

  // 4. 메시지가 영문/숫자로만 구성되어 있는지 확인
  if (message && /^[A-Za-z0-9\s]*$/.test(message)) {
    message = i18n.t('validation:temporaryErrorOccurred');
  }

  if (!message) {
    return {
      title: i18n.t('validation:temporaryErrorOccurred'),
      message: i18n.t('validation:tryAgainLater'),
    };
  }

  return { message };
};
