import { useEffect, useMemo } from 'react';
import { clearAuthData, kickOut } from '~/features/logout-and-clear-data/lib/clear-app-data';
import { CBDCAxiosFallbackProps } from '~/shared/@types/error';
import i18n from '~/shared/i18n/i18n';
import { Dialog, DialogProps } from '~/shared/ui/dialogs/dialog';

export const KickOutErrorFallback = ({ error, resetErrorBoundary }: CBDCAxiosFallbackProps) => {
  useEffect(() => {
    console.error('[ErrorBoundary] Kickout Error', JSON.stringify(error.response?.data));
    clearAuthData();
  }, [error]);

  const msg = useMemo(() => {
    let message: Partial<DialogProps> = {
      title: i18n.t('validation:temporaryErrorOccurred'),
      message: i18n.t('validation:tryAgainLater'),
    };
    if (error?.response?.data?.message) {
      message = { message: error.response.data.message };
    }
    return message;
  }, [error]);

  const handleCancel = () => {
    resetErrorBoundary?.();
  };

  const handleConfirm = () => {
    resetErrorBoundary?.();
    kickOut();
  };

  return (
    <Dialog
      afterLeave={() => null}
      open={true}
      onClose={() => null}
      onConfirmClick={handleConfirm}
      onCancelClick={handleCancel}
      message={msg.message}
    />
  );
};
