export type RouteNamesType = typeof ROUTE_NAMES;
type RouteNamesKeyType = keyof RouteNamesType;
type RouteType = {
  lazy: (args?: unknown) => Promise<{
    Component: React.ComponentType | null;
    loader?: () => Promise<unknown>;
  }>;
};

type NestedType<T, Path extends string> = Path extends `${infer Key}.${infer Rest}`
  ? Key extends keyof T
    ? NestedType<T[Key], Rest>
    : never
  : Path extends keyof T
    ? T[Path]
    : never;

export type RouteConfig<Path extends string> = Omit<
  NestedType<RouteNamesType, Path> extends infer U ? (U extends object ? { [K in keyof U]: RouteType } : never) : never,
  'base'
>;

export type RootRouteConfig = { [K in RouteNamesKeyType]: RouteType };
