import { BankCode } from '~/shared/@types/banking-code';
import { RELEASE_VERSION } from '~/shared/config/environment';
import { createAppConfigMap } from './config';
import { Env } from './types';

/**
 * Main configuration hub
 * This simplified approach uses a single configuration factory
 * instead of separate environment-specific files
 */
function getAppConfig(bankCode: BankCode) {
  // We now use a single config map for all environments
  const configMap = createAppConfigMap();
  return configMap[bankCode];
}

/**
 * 환경변수에서 전달받은 환경값 ( mockup | development | stage | production )
 * 이 값으로 api 호출 URL 세팅
 */
const ENV: Env = (import.meta.env.VITE_APP_ENV ?? 'development') as Env;
/**
 * 환경변수에서 전달받은 bank key ( A | B | C | D | E )
 */
const BANK_CODE: BankCode = (import.meta.env.VITE_APP_BANK ?? 'AAA') as BankCode;
const WEB_VERSION = RELEASE_VERSION ?? '1.0.0';

export const appConfig = getAppConfig(BANK_CODE);
