import * as Sentry from '@sentry/react';
import axios, { HttpStatusCode } from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { IS_MOCK_PHASE } from '~/shared/config/environment';

export class KickOutError extends Error {
  constructor(...args: ConstructorParameters<ErrorConstructor>) {
    super(...args);
    console.error(...args);
  }
}

// CBDCAxiosError가 아니라면 상위 Error Boundary로 위임
export const checkIsAxiosError = (error: Error): error is CBDCAxiosError => axios.isAxiosError(error);

export const checkNoPermission = (error: CBDCAxiosError) => {
  const status = error.response?.status;
  return !IS_MOCK_PHASE && (status === HttpStatusCode.Unauthorized || status === HttpStatusCode.Forbidden);
};

export const checkIsKickOutError = (error: KickOutError) => {
  if (error instanceof KickOutError) {
    return true;
  }
};

export const checkIsNetworkError = () => {
  return navigator.onLine === false;
};

export class CustomError extends Error {
  constructor(...args: ConstructorParameters<ErrorConstructor>) {
    super(...args);
    console.error(...args);
    Sentry.withScope((scope) => {
      scope.setTag('ignore', 'true');
      Sentry.captureException(args);
    });
  }
}
