import { ROUTE_NAMES } from '~/shared/routes/route-names';

export type PathType = RouteNamesType[keyof RouteNamesType];

type RouteNamesType = typeof ROUTE_NAMES;

const generatePath = (base: string, path?: string): string => {
  if (path === '/') return path;
  base = base.replace(/\/\*/g, '').replace(/\/+$/, '');
  if (typeof path === 'string') {
    path = path.replace(/:.*/, '').replace(/^\/+/, '');
  }
  return path ? `${base}/${path}` : base;
};

type BuildPaths<T, B extends string = ''> = T extends string
  ? string
  : T extends { base: string }
    ? {
        [K in Exclude<keyof T, 'base'>]: BuildPaths<T[K], ReturnType<typeof generatePath>>;
      }
    : {
        [K in keyof T]: BuildPaths<T[K], B>;
      };

function buildPaths<T>(routeNames: T, basePath: string = ''): BuildPaths<T, typeof basePath> {
  const paths = {} as BuildPaths<T, typeof basePath>;

  for (const key in routeNames) {
    const value = routeNames[key];

    if (key === 'base') {
      // Skip base keys
      continue;
    }

    if (key === 'root') {
      // For 'root' keys, use the path without wildcards
      // Extract the base path from the parent object's base property
      const parentBase = (routeNames as any).base;
      if (parentBase) {
        const basePathValue = parentBase.replace(/\/\*$/, '');
        (paths as any)[key] = basePathValue;
      } else {
        (paths as any)[key] = basePath || '/';
      }
      continue;
    }

    if (typeof value === 'string') {
      (paths as any)[key] = generatePath(basePath, value);
    } else if (typeof value === 'object' && value !== null) {
      const newBasePath = (value as any).base ? generatePath(basePath, (value as any).base) : basePath;
      (paths as any)[key] = buildPaths(value, newBasePath);
    }
  }

  return paths;
}

export const PATHS = buildPaths(ROUTE_NAMES);

export const BACK_BLOCKED_PATHS = {
  [PATHS.home]: [PATHS.root, PATHS.intro, PATHS.mobileVerification, PATHS.pin.input, PATHS.pin.set],
};
