import { SwitchCase } from '@toss/react';
import { memo } from 'react';
import { DefaultLabel } from './default-label';
import { RadioLabel } from './radio-label';
import { SelectStyle, LabelChangeProps, SelectOption, OnClickProps } from './types';

type SelectItemProps = {
  option: SelectOption<unknown>;
  index: number;
  isSelected: boolean;
  selectStyle: SelectStyle;
  onRadioChange: (props: LabelChangeProps<unknown>) => void;
  onClick: (props: OnClickProps<unknown>) => void;
  refs: React.MutableRefObject<(HTMLElement | null)[]>;
};

export const BaseSelectItem = memo(
  ({ option, index, isSelected, selectStyle, onRadioChange, onClick, refs }: SelectItemProps) => {
    return (
      <SwitchCase
        value={selectStyle}
        caseBy={{
          [SelectStyle.RADIO]: (
            <RadioLabel
              ref={(el: HTMLElement | null) => (refs.current[index] = el)}
              option={option}
              isSelected={isSelected}
              onRadioChange={onRadioChange}
              onClick={onClick}
              disabled={option.disabled}
            />
          ),
          [SelectStyle.DEFAULT]: (
            <DefaultLabel
              ref={(el: HTMLElement | null) => (refs.current[index] = el)}
              option={option}
              isSelected={isSelected}
              onRadioChange={onRadioChange}
              onClick={onClick}
              disabled={option.disabled}
            />
          ),
        }}
      />
    );
  },
);

BaseSelectItem.displayName = 'SelectItem';
