import { RegisterOptions, UseFormRegister } from 'react-hook-form';

export type ElementType<T> = T extends (infer U)[] ? U : never;

export type LabelEvent = React.ChangeEvent<HTMLInputElement> | React.MouseEvent<HTMLInputElement>;

export type LabelChangeProps<T> = {
  event: LabelEvent;
  option: SelectOption<T>;
};

export type OnClickProps<T = unknown> = {
  event: React.MouseEvent<HTMLInputElement>;
  option: SelectOption<T>;
};

export enum SelectStyle {
  DEFAULT = 'default',
  RADIO = 'radio',
}

export type SelectOption<T> = {
  label: string;
  value: T;
  description?: string;
  disabled?: boolean;
};

export type SelectState<T = unknown> = {
  options: SelectOption<T>[];
  selectedOption?: SelectOption<T>;
  valueKey?: keyof T;
};

export type SelectConfirmProps<T = unknown> = {
  event: React.MouseEvent<HTMLButtonElement>;
  selectedOption: SelectOption<T>;
};

export type BaseSelectListProps<T = unknown> = SelectState<T> & {
  description?: string | JSX.Element;
  defaultSelectedOption?: SelectOption<T>;
  onLabelChange?: ({ event, option }: LabelChangeProps<T>) => void;
  selectStyle?: SelectStyle;
  shouldShowConfirmButton?: boolean;
  confirmButtonLabel?: string;
  onConfirm?: (props: SelectConfirmProps<T>) => void;
  maxHeight?: string;
  className?: string;
};

export type SelectListProps<T = unknown> = SelectState<T> & {
  defaultSelectedOption?: SelectOption<T>;
  onSelect: (option: SelectOption<T>) => void;
  selectStyle?: SelectStyle;
};

export type LabelProps<T> = {
  option: SelectOption<T>;
  isSelected: boolean;
  onRadioChange: (props: LabelChangeProps<T>) => void;
  onClick: (props: OnClickProps<T>) => void;
  disabled?: boolean;
};

export type SelectBottomSheetProps<T> = SelectState<T> & {
  title?: string | JSX.Element;
  description?: string;
  selectStyle?: SelectStyle;
  shouldShowConfirmButton?: boolean;
  confirmButtonLabel?: string;
  onRadioChange?: (props: LabelChangeProps<T>) => void;
  onConfirm?: (props: SelectConfirmProps<T>) => void;
  onClose?: () => void;
};

export type SelectProps = {
  placeholder: string;
  labels: string[];
  values: string[];
  name: string;
  option?: RegisterOptions;
  readOnly?: boolean;
  onClick?: () => void;
  classStr?: string;
  disabled?: boolean;
  description?: string;
  isErrorPaddingPresent?: boolean;
};

export type BankSelectProps = {
  placeholder: string;
  name: string;
  option?: RegisterOptions<any>;
  readOnly?: boolean;
  onClick?: () => void;
  register: UseFormRegister<any>;
  classStr?: string;
  defaultValue?: string;
  isShowError?: boolean;
  isErrorPaddingPresent?: boolean;
};
