import * as Sentry from '@sentry/react';
import axios, { AxiosError, AxiosResponse, HttpStatusCode, InternalAxiosRequestConfig } from 'axios';
import { useStore } from '~/app/store/store';
import { WHITE_LIST_URLS } from '~/shared/api/api-urls';
import { StorageKeys } from '~/shared/config/local-storage';
import { checkIsAxiosError, getLocalStorage } from '~/shared/lib';
import { extractAccessToken, finalizeConfig } from './utils';

const onRequestFulfilled = (config: InternalAxiosRequestConfig) => {
  const token = useStore.getState().authSlice.jwt;

  const subUrl = (config?.url ?? '').split('?');
  if (WHITE_LIST_URLS.includes(subUrl[0])) {
    delete config.headers.Authorization;
    return finalizeConfig(config);
  }

  config.headers.Authorization = token ? `Bearer ${token}` : null;
  config.headers['X-Request-id'] = getLocalStorage(StorageKeys.RequestId) ?? '';
  return finalizeConfig(config);
};

const onRequestRejected = (error: AxiosError) => {
  const { method, url, params, data, headers } = error?.config ?? {};
  Sentry.setContext('API Request Detail', {
    method,
    url,
    params,
    data,
    headers,
  });

  return Promise.reject(error);
};

const onResponseFulfilled = (response: AxiosResponse) => {
  if (response.status === 204) {
    return Promise.resolve(null) as unknown as Promise<AxiosResponse<unknown, unknown>>;
  }
  extractAccessToken(response);

  return {
    ...response,
    data: response.data,
  };
};

const onResponseRejected = (error: AxiosError) => {
  if (error?.response) {
    const { data, status } = error.response;

    if (status >= HttpStatusCode.InternalServerError && status <= HttpStatusCode.NetworkAuthenticationRequired) {
      // const proxyHost = import.meta.env.VITE_APP_PROXY_HOST || 'Not configured';
      // const proxyPort = import.meta.env.VITE_APP_PROXY_PORT || 'Not configured';
      // notifyServerError(
      //   proxyHost,
      //   proxyPort,
      //   JSON.stringify({
      //     status,
      //     data,
      //     url: error.config?.url,
      //     method: error.config?.method,
      //   }),
      // ).catch(console.error);
    }

    Sentry.setContext('API Response Detail', {
      status,
      data,
    });
  }
  return new Promise((_resolve, reject) => {
    if (checkIsAxiosError(error)) {
      setTimeout(() => reject(error), 300);
    } else {
      reject(error);
    }
  });
};

export const initAxios = () => {
  axios.defaults.withCredentials = true;
  axios.defaults.timeout = 10000;
  axios.defaults.transitional = {
    clarifyTimeoutError: true,
    forcedJSONParsing: true,
    silentJSONParsing: true,
  };
  axios.defaults.headers.common['Content-Type'] = 'application/json;charset=UTF-8';

  axios.interceptors.request.use(onRequestFulfilled, onRequestRejected);
  axios.interceptors.response.use(onResponseFulfilled, onResponseRejected);
};
