import { useState } from 'react';
import { FallbackProps } from 'react-error-boundary';
import { parseError } from '~/shared/lib/utils/error-message';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type CommonErrorProps = FallbackProps & {
  buttonLabel?: string[];
  onConfirmClick?: () => void;
};

export const CommonErrorFallback = ({ error, resetErrorBoundary, buttonLabel, onConfirmClick }: CommonErrorProps) => {
  const [isOpen, setIsOpen] = useState(true);

  // validation 에러 메시지 처리
  const errorMessage = (error as any).validationErrors
    ? (error as any).validationErrors[0].message
    : parseError(error).message;

  const handleCancel = () => {
    try {
      history?.back();
      setTimeout(() => {
        resetErrorBoundary();
      }, 0);
    } catch (e) {
      location.href = '/';
    }
  };

  const handleConfirm = () => {
    onConfirmClick?.();
    resetErrorBoundary();
  };

  return (
    <Dialog
      afterLeave={() => null}
      open={isOpen}
      onClose={() => setIsOpen(false)}
      onConfirmClick={handleConfirm}
      onCancelClick={handleCancel}
      title={parseError(error).title}
      message={errorMessage}
      buttonLabel={buttonLabel}
    />
  );
};
