import { lens } from '@dhmk/zustand-lens';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';

export type ExchangeState = {
  lastTrnscTypeCd?: TrnscTypeCd;
  tokenId?: string;
  setLastTrnscTypeCd: (trnscTypeCd: TrnscTypeCd) => void;
  getLastTrnscTypeCd: () => TrnscTypeCd | undefined;
  clearLastTrnscTypeCd: () => void;
  setTokenId: (tokenId: string) => void;
  getTokenId: () => string | undefined;
  clearTokenId: () => void;
};

const initialState = {} as ExchangeState;

export const createExchangeSlice = lens<ExchangeState>((set, get) => ({
  ...initialState,

  // 마지막 거래 유형 코드 저장
  setLastTrnscTypeCd: (trnscTypeCd: TrnscTypeCd) => {
    if (!trnscTypeCd) return;

    set((state: ExchangeState) => {
      // 현재 값과 다른 경우에만 업데이트
      if (state.lastTrnscTypeCd !== trnscTypeCd) {
        return {
          ...state,
          lastTrnscTypeCd: trnscTypeCd,
        };
      }
      return state;
    });
  },

  // 마지막 거래 유형 코드 조회
  getLastTrnscTypeCd: () => {
    return get().lastTrnscTypeCd;
  },

  // 마지막 거래 유형 코드 초기화
  clearLastTrnscTypeCd: () => {
    set((state: ExchangeState) => ({
      ...state,
      lastTrnscTypeCd: undefined,
    }));
  },

  // 토큰 ID 저장
  setTokenId: (tokenId: string) => {
    if (!tokenId) return;

    set((state: ExchangeState) => {
      // 현재 값과 다른 경우에만 업데이트
      if (state.tokenId !== tokenId) {
        return {
          ...state,
          tokenId,
        };
      }
      return state;
    });
  },

  // 토큰 ID 조회
  getTokenId: () => {
    return get().tokenId;
  },

  // 토큰 ID 초기화
  clearTokenId: () => {
    set((state: ExchangeState) => ({
      ...state,
      tokenId: undefined,
    }));
  },
}));
