import { overlay as overlayKit } from 'overlay-kit';

type OverlayType = typeof overlayKit;

type Overlay = OverlayType & {
  exclusiveOpen: typeof overlayKit.open;
};

export const overlay: Overlay = {
  ...overlayKit,
  exclusiveOpen: (controller, options) => {
    overlayKit.unmountAll();
    return overlayKit.open(controller, options);
  },
};
