export type DialogButtonsProps = {
  buttonLabel: string[];
  onConfirm: () => void;
  onCancel: () => void;
};

export const DialogButtons = ({ buttonLabel, onConfirm, onCancel }: DialogButtonsProps) => {
  if (buttonLabel.length === 0) {
    return null;
  }

  if (buttonLabel.length === 1) {
    return (
      <div className="modal-dialog-footer">
        <button type="button" className="btn-modal-confirm" onClick={onConfirm}>
          {buttonLabel[0]}
        </button>
      </div>
    );
  }

  return (
    <div className="modal-dialog-footer">
      {buttonLabel[0] && (
        <button type="button" className="btn-modal-cancel" onClick={onCancel}>
          {buttonLabel[0]}
        </button>
      )}
      {buttonLabel[1] && (
        <button type="button" className="btn-modal-confirm" onClick={onConfirm}>
          {buttonLabel[1]}
        </button>
      )}
    </div>
  );
};
