import { lens } from '@dhmk/zustand-lens';
import { UserResponse } from '~/entities/pin/api/dtos/schemas';
import { PIN_CONSTANTS } from '~/entities/pin/lib/constants';
import { PinInteractionMode } from '~/shared/api/dtos/enums';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import { PinInterface, PinState } from './types';

const isSequentialOrSameNumber = (password: string): boolean => {
  const sequentialNumberRegex =
    /00|11|22|33|44|55|66|77|88|99|012|123|234|345|456|567|678|789|987|876|765|654|543|432|321|210/g;
  if (sequentialNumberRegex.test(password)) {
    return true;
  }
  return false;
};

const fnShuffle = () => {
  if (document.querySelector('[aria-label="재배열"]')) {
    window.mtk.relocate(new MouseEvent('click'), document.querySelector('[aria-label="재배열"]'));
  }
};

export const close = () => {
  (window.mtk as any)?.close?.();
};

// 초기 상태 정의
const initialState: PinInterface = {
  pin: '',
  title: '',
  message: '',
  step: PIN_CONSTANTS.STEP.FIRST,
  prevPin: '',
  isError: false,
  isLoading: false,
  incorrectPinCount: 0,
  type: PinInteractionMode.로그인,
  callbacks: {},
};

// Zustand 스토어 생성
export const createPinSlice = lens<PinState>((set, get) => ({
  ...initialState,

  // 상태 설정 함수들
  setPin: (update) => set((state) => ({ pin: typeof update === 'function' ? update(state.pin) : update })),

  setStep: (update) =>
    set((state) => {
      return {
        step: typeof update === 'function' ? update(state.step) : update,
      };
    }),

  setIsError: (update) =>
    set((state) => ({
      isError: typeof update === 'function' ? update(state.isError) : update,
    })),

  setIsLoading: (update) =>
    set((state) => ({
      isLoading: typeof update === 'function' ? update(state.isLoading) : update,
    })),

  setIncorrectPinCount: (update) =>
    set((state) => ({
      incorrectPinCount: typeof update === 'function' ? update(state.incorrectPinCount) : update,
    })),

  setType: (update) =>
    set((state) => ({
      type: typeof update === 'function' ? update(state.type) : update,
    })),

  // 콜백 설정 함수
  setCallbacks: (callbacks) =>
    set((state) => ({
      callbacks: { ...state.callbacks, ...callbacks },
    })),

  // 이벤트 트리거 함수들
  triggerCompleteInput: () => {
    const { callbacks } = get();
    callbacks.onCompleteInput?.();
  },

  triggerError: (message) => {
    const { callbacks } = get();
    callbacks.onError?.(message);
  },

  triggerMaxFailure: () => {
    const { callbacks } = get();
    callbacks.onMaxFailure?.();
  },

  triggerCancel: () => {
    const { callbacks } = get();
    callbacks.onCancel?.();
  },

  // 복합 액션들
  handleErrorMessage: (error, count) => {
    set({
      isError: true,
      message: error,
      pin: '',
      incorrectPinCount: count !== undefined && count !== null ? count : get().incorrectPinCount,
    });
    fnShuffle();

    // 에러 이벤트 트리거
    get().triggerError(error);
  },

  handleDeleteDigit: () => {
    const { pin } = get();
    if (pin.length > 0) {
      set({ pin: pin.slice(0, -1) });
    }
  },

  fnChkUserData: (chkPin) => {
    try {
      // getGlobalQueryClient를 통해 사용자 정보 가져오기
      const userRes = getGlobalQueryClient().getQueryData<UserResponse>(
        queries.cstr.cstmr({ cstmrNo: 'detail' }).queryKey,
      );

      if (chkPin && userRes?.tbCstmrMastr?.mbtlnum && userRes?.tbCstmrMastr?.rlnmNo) {
        // 휴대폰 번호의 마지막 4자리
        const mbtlnum = (userRes.tbCstmrMastr.mbtlnum || '').slice(-4);
        // 주민등록번호
        const rlnmNo = userRes.tbCstmrMastr.rlnmNo || '';

        // PIN에 휴대폰 번호 마지막 4자리가 포함되어 있는지 확인
        if (chkPin.includes(mbtlnum)) return true;

        // 주민등록번호에 PIN이 포함되어 있는지 확인
        if (rlnmNo.includes(chkPin)) return true;
      }

      return false;
    } catch (error) {
      console.error('사용자 데이터 검증 오류:', error);
      return false; // 에러 발생 시 기본값으로 false 반환
    }
  },

  handleSetDigit: (value) => {
    const { pin } = get();
    if (pin.length < PIN_CONSTANTS.PIN_LENGTH) {
      set({ pin: pin + value });
    }
  },

  resetAll: () => {
    const { callbacks } = get();
    set({ ...initialState, callbacks });
  },

  clearPin: () => {
    set({ pin: '' });
  },

  handleShuffle: () => {
    fnShuffle();
  },

  initializeWithProps: (props) => {
    const updates: Partial<PinInterface> = {};

    if (props.title) updates.title = props.title;
    if (props.message) updates.message = props.message;
    if (props.step) updates.step = props.step;
    if (props.prevPin) updates.prevPin = props.prevPin;
    if (props.pin) updates.pin = props.pin;
    if (typeof props.isError === 'boolean') updates.isError = props.isError;
    if (props.type) updates.type = props.type;

    set(updates);

    // 콜백도 초기화
    if (props.callbacks) {
      get().setCallbacks(props.callbacks);
    }
  },

  // PIN 유틸리티 함수들
  isPinEmpty: (customPin?: string) => {
    const pin = customPin ?? get().pin;
    return !pin || pin.length === 0;
  },

  isPinLengthValid: (customPin?: string) => {
    const pin = customPin ?? get().pin;
    return !!pin && pin.length >= PIN_CONSTANTS.PIN_LENGTH;
  },

  isPinLengthInvalid: (customPin?: string) => {
    const pin = customPin ?? get().pin;
    return !pin || pin.length < PIN_CONSTANTS.PIN_LENGTH;
  },

  shouldClearPinError: (customPin?: string) => {
    const pin = customPin ?? get().pin;
    return !!pin && pin.length > 0;
  },

  clearPinError: () => {
    if (get().shouldClearPinError()) {
      set({ isError: false });
    }
  },

  isSequentialOrSameNumber,

  calculateFailCount: (currentFailCount) => {
    return Number(currentFailCount ?? PIN_CONSTANTS.INITIAL_FAIL_COUNT) > PIN_CONSTANTS.MAX_FAIL_COUNT
      ? PIN_CONSTANTS.MAX_FAIL_COUNT
      : Number(currentFailCount ?? PIN_CONSTANTS.INITIAL_FAIL_COUNT);
  },

  shouldShowPinError: (failCount, isFail) => {
    return failCount > 0 && !isFail;
  },

  isFailCountInitRequired: (failCount) => {
    return failCount === null || failCount === undefined;
  },

  handlePinFailure: (failCount, options) => {
    const msg = failCount > 0 ? options.message : '';
    get().handleErrorMessage(msg);

    if (failCount > PIN_CONSTANTS.MAX_INCORRECT_COUNT) {
      if (options.onMaxFailure) {
        options.onMaxFailure();
      } else {
        get().triggerMaxFailure();
      }
    }
  },

  resetPropsOnError: (props) => {
    set({
      ...get(),
      incorrectPinCount: 0,
      prevPin: '',
      step: PIN_CONSTANTS.STEP.FIRST,
      title: props.title,
      message: props.message,
      isError: false,
      pin: '',
    });
    get().handleShuffle();
  },
  setPropsOnSecondStep: (props) => {
    set({
      ...get(),
      incorrectPinCount: 0,
      prevPin: get().pin,
      step: 2,
      title: props.title, //i18n.t('pin:titleSetPinConfirm'),
      message: props.message, // i18n.t('pin:messageSetPinConfirm'),
      isError: false,
      pin: '',
    });
    get().handleShuffle();
  },
  setPropsOnCompleteStep: (props) => {
    get().triggerCompleteInput();
    set({
      ...get(),
      incorrectPinCount: 0,
      prevPin: '',
      step: 1,
      title: props.title, //i18n.t('pin:titleSetPin'),
      message: props.message, //i18n.t('pin:messageSetPin'),
      isError: false,
      pin: '',
    });
  },
}));
