import { lens } from '@dhmk/zustand-lens';
import { AppParams } from '~/entities/super-app/model/types';

export type SuperAppState = {
  decData: AppParams;
  setDecData: (decData: AppParams) => void;
  clearSuperAppData: () => void;
};
const initialState = {
  decData: {},
} as SuperAppState;

export const createSuperAppSlice = lens<SuperAppState>((set) => ({
  ...initialState,
  setDecData: (decData: AppParams) => {
    set((state: SuperAppState) => {
      return {
        ...state,
        decData,
      };
    });
  },
  clearSuperAppData: () => set(initialState),
}));
